"use client";

import React from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import ProductSlider from "@/components/ProductSlider";
import { ProductCardSkeleton } from "@/components/ProductCard";
import { getFeaturedProducts, products } from "@/lib/products";
import { ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";

const fadeUp = {
  hidden: { opacity: 0, y: 32 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.5, ease: "easeOut" } },
};

interface FeaturedProductsProps {
  limit?: number;
  title?: string;
  showViewAll?: boolean;
}

export default function FeaturedProducts({
  limit = 8,
  title = "Featured Products",
  showViewAll = true,
}: FeaturedProductsProps) {
  const featuredProducts = getFeaturedProducts(limit);
  const displayProducts =
    featuredProducts.length >= limit
      ? featuredProducts
      : [...featuredProducts, ...products.slice(0, limit - featuredProducts.length)];

  return (
    <section className="py-12 md:py-20 bg-white">
      <div className="container-custom">
        {/* Section Header */}
        <motion.div
          className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
        >
          <div>
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900">
              {title}
            </h2>
            <p className="text-gray-600 mt-2">Discover our most loved products</p>
          </div>

          {showViewAll && (
            <Link href="/shop" className="hidden md:block">
              <Button variant="outline" className="gap-2">
                View All Products
                <ArrowRight className="h-4 w-4" />
              </Button>
            </Link>
          )}
        </motion.div>

        {/* Luxury Product Slider */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.1 }}
          transition={{ delay: 0.1 }}
        >
          <ProductSlider products={displayProducts} />
        </motion.div>

        {/* Mobile View All */}
        {showViewAll && (
          <div className="md:hidden text-center mt-8">
            <Link href="/shop">
              <Button className="gap-2">
                View All Products
                <ArrowRight className="h-4 w-4" />
              </Button>
            </Link>
          </div>
        )}
      </div>
    </section>
  );
}

export function FeaturedProductsSkeleton({ count = 3 }: { count?: number }) {
  return (
    <section className="py-12 md:py-20 bg-white">
      <div className="container-custom">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
          <div className="space-y-2">
            <div className="h-10 w-64 bg-gray-200 rounded animate-pulse" />
            <div className="h-5 w-48 bg-gray-200 rounded animate-pulse" />
          </div>
          <div className="h-10 w-40 bg-gray-200 rounded animate-pulse" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
          {Array.from({ length: count }).map((_, i) => (
            <ProductCardSkeleton key={i} />
          ))}
        </div>
      </div>
    </section>
  );
}
