"use client";

import { motion } from "framer-motion";
import { Truck, ShieldCheck, RotateCcw, Headphones } from "lucide-react";

const containerVariants = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.1 } },
};

const cardVariants = {
  hidden: { opacity: 0, y: 32 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.5, ease: "easeOut" } },
};

const trustSignals = [
  {
    icon: Truck,
    title: "Fast Delivery",
    description: "Karachi-wide same day dispatch",
  },
  {
    icon: ShieldCheck,
    title: "100% Authentic",
    description: "Genuine branded products only",
  },
  {
    icon: RotateCcw,
    title: "Easy Returns",
    description: "Hassle-free 7-day return policy",
  },
  {
    icon: Headphones,
    title: "24/7 Support",
    description: "Always here on WhatsApp for you",
  },
];

interface TrustSignalsProps {
  variant?: "banner" | "compact";
}

export default function TrustSignals({ variant = "banner" }: TrustSignalsProps) {
  return (
    <section className={`bg-[#529538] ${variant === "compact" ? "py-6" : "py-12"}`}>
      <div className="container-custom">
        <motion.div
          className="grid grid-cols-2 md:grid-cols-4 gap-6 md:gap-8"
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.2 }}
        >
          {trustSignals.map((signal) => {
            const Icon = signal.icon;
            return (
              <motion.div
                key={signal.title}
                variants={cardVariants}
                className="flex flex-col items-center text-center p-6 transition-all hover:scale-105"
              >
                {/* Icon Container: Glassmorphism */}
                <div className="bg-white/10 backdrop-blur-sm p-4 rounded-full mb-4 border border-white/20">
                  <Icon className="h-6 w-6 text-white" />
                </div>

                {/* Text */}
                <h3 className="font-bold text-white mb-1 uppercase tracking-wider text-sm md:text-base">
                  {signal.title}
                </h3>
                <p className="text-sm text-white/70 italic font-light">
                  {signal.description}
                </p>
              </motion.div>
            );
          })}
        </motion.div>
      </div>
    </section>
  );
}
